#!/usr/bin/env python3
"""Build the embeddable 'Cyber attacks — incidents to watch now' card for other WMM sites (wmm-hoa.com, gcsme.kr).
Reads the incidents already published and verified on /cyber/ (ko) and /cyber/en/, keeps the newest 6, and writes
cf/extra/cyber/card.js (self-contained: data + styles in a shadow root, no fetch, no cookies, no tracking) and a preview page.
Host page usage:  <div data-gv-cyber data-site="wmm|gcsme" data-theme="dark|light" data-lang="ko|en" data-n="4"></div>
                  <script src="https://radar.wmm-hoa.com/cyber/card.js" defer></script>"""
import html, json, os, re
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); CY = os.path.join(ROOT, "cf", "extra", "cyber")
def txt(s): return html.unescape(re.sub(r"<[^>]+>", "", s)).strip()
def parse(path):
    t = open(path, encoding="utf-8").read(); out = []
    for m in re.finditer(r'(?s)<article class="ev" data-v="(\w+)"[^>]*>(.*?)</article>', t):
        v, b = m.group(1), m.group(2)
        d = re.search(r'(?s)<div class="d"><b>(.*?)</b>(.*?)</div>', b)
        ty = re.search(r'<span class="bd ty">(.*?)</span>', b); h = re.search(r"(?s)<h3>(.*?)</h3>", b)
        j = re.search(r'(?s)<p class="j"><b>[^<]*</b>\s*·?\s*(.*?)</p>', b)
        src = re.findall(r'<a href="(https?://[^"]+)"[^>]*>(.*?)</a>', re.search(r'(?s)<p class="sr">(.*?)</p>', b).group(1)) if 'class="sr"' in b else []
        seen = []; [seen.append((u, txt(n))) for u, n in src if u not in [x[0] for x in seen]]
        out.append({"v": v, "d": txt(d.group(1)), "w": txt(d.group(2)), "ty": txt(ty.group(1)) if ty else "", "t": txt(h.group(1)),
                    "j": txt(j.group(1)) if j else "", "s": [{"u": u, "n": n} for u, n in seen[:2]]})
    asof = re.search(r"기준일 (\d{4}-\d{2}-\d{2})", t) or re.search(r"(\d{4})\.(\d{2})\.(\d{2})", t)
    return out, asof
ko, a = parse(os.path.join(CY, "index.html")); en, _ = parse(os.path.join(CY, "en", "index.html"))
asof = a.group(1) if a and a.lastindex == 1 else (ko[0]["d"].replace(".", "-") if ko else "")
D = {"ko": ko[:6], "en": en[:6], "asof": asof}
JS = r"""/* GOV RADAR · cyber incidents card (generated by tools/cyber_card.py — do not edit by hand) */
(function(){var D=__DATA__,B="https://radar.wmm-hoa.com";
var T={ko:{h:"사이버 공격 — 지금 주목할 사건",all:"전체 사건·판정 기준 보기",asof:"기준일",src:"출처",j:"판정",
 v:{atk:"실제 공격",susp:"조사 중·의심",no:"공격 아님",vuln:"취약점"},
 lead:{wmm:"장애가 났다고 모두 해킹은 아닙니다. GOV RADAR가 사건마다 확인된 판정과 원문 출처를 붙여 둡니다.",
       gcsme:"기업은 업무 연속성(BCP), 공급망·외주업체 점검, 원격접속 관리, 모의훈련으로 대비합니다. 사건별 판정과 원문 출처는 GOV RADAR에서 확인하세요."},
 note:"배후·피해 규모는 공식 발표 전까지 확정하지 않습니다.",url:"/cyber/"},
 en:{h:"Cyber attacks — incidents to watch now",all:"See all incidents and how we judge them",asof:"As of",src:"Source",j:"Verdict",
 v:{atk:"Confirmed attack",susp:"Under investigation",no:"Not an attack",vuln:"Vulnerability"},
 lead:{wmm:"Not every outage is a hack. GOV RADAR labels each incident with what has been confirmed and links the original source.",
       gcsme:"Companies prepare with business continuity plans, supplier and outsourcer checks, remote-access control and drills. Verdicts and sources are on GOV RADAR."},
 note:"Attribution and damage figures stay unconfirmed until officially announced.",url:"/cyber/en/"}};
var FF='@font-face{font-family:"GV Nexon";font-weight:400;font-display:swap;src:local("NEXON Lv1 Gothic OTF"),url('+B+'/assets/fonts/NEXONLv1GothicOTF.woff) format("woff")}'+
'@font-face{font-family:"GV Nexon";font-weight:700;font-display:swap;src:local("NEXON Lv1 Gothic OTF Bold"),url('+B+'/assets/fonts/NEXONLv1GothicOTFBold.woff) format("woff")}';
var CSS=':host{all:initial;display:block}*{box-sizing:border-box}'+
'.c{font-family:"GV Nexon","NEXON Lv1 Gothic OTF",sans-serif;background:#0d1b2e;color:#fff;padding:28px 24px;line-height:1.5;-webkit-font-smoothing:antialiased}'+
'h2{font-size:24px;font-weight:700;margin:0 0 8px;letter-spacing:-.01em}.ld{font-size:16px;color:#d3dbe6;margin:0 0 20px;max-width:720px}'+
'.g{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}'+
'.e{background:#fff;color:#0d1b2e;padding:16px;display:flex;flex-direction:column;gap:6px;min-width:0}'+
'.m{font-size:13px;color:#4a5668}.vd{font-size:14px;font-weight:700}.vd i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px;vertical-align:1px}'+
'.atk i{background:#c62828}.susp i{background:#e08a00}.no i{background:#2e7d32}.vuln i{background:#5b4bc4}'+
'h3{font-size:17px;font-weight:700;margin:2px 0;line-height:1.4;overflow-wrap:anywhere}.j{font-size:14px;color:#2b3645;margin:0;overflow-wrap:anywhere}'+
'.s{font-size:13px;margin-top:auto;padding-top:6px}.s a{color:#0b57d0;text-decoration:underline}'+
'.f{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px 20px;align-items:center;margin-top:18px;font-size:14px;color:#d3dbe6}'+
'.go{display:inline-block;background:#fff;color:#0d1b2e;font-weight:700;padding:11px 18px;text-decoration:none;font-size:15px}.go:focus-visible,.s a:focus-visible{outline:3px solid #ffd54f;outline-offset:2px}'+
'.lt.c{background:#fff;color:#14231f;border-top:4px solid #1d3a34}.lt .ld,.lt .f{color:#3b4a45}.lt .e{background:#f6f4ee;color:#14231f}.lt .go{background:#1d3a34;color:#fff}'+
'@media(max-width:520px){.c{padding:22px 16px}h2{font-size:21px}}';
function esc(s){return String(s||"").replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function render(el){if(el.__gv)return;el.__gv=1;var L=(el.getAttribute("data-lang")||document.documentElement.lang||"ko").slice(0,2)==="en"?"en":"ko",
 S=el.getAttribute("data-site")==="gcsme"?"gcsme":"wmm",n=Math.max(3,Math.min(6,+el.getAttribute("data-n")||4)),t=T[L],rows=(D[L]||[]).slice(0,n);
 var h='<style>'+CSS+'</style><section class="c'+(el.getAttribute("data-theme")==="light"?" lt":"")+'" lang="'+L+'" aria-label="'+esc(t.h)+'"><h2>'+esc(t.h)+'</h2><p class="ld">'+esc(t.lead[S])+'</p><div class="g">';
 rows.forEach(function(r){h+='<article class="e"><div class="m">'+esc(r.d)+' · '+esc(r.w)+(r.ty?' · '+esc(r.ty):'')+'</div><div class="vd '+r.v+'"><i></i>'+esc(t.v[r.v]||r.v)+'</div><h3>'+esc(r.t)+'</h3>'+
  (r.j?'<p class="j">'+esc(r.j)+'</p>':'')+(r.s.length?'<div class="s">'+t.src+' · '+r.s.map(function(s){return'<a href="'+esc(s.u)+'" target="_blank" rel="noopener nofollow">'+esc(s.n)+'</a>'}).join(' · ')+'</div>':'')+'</article>'});
 h+='</div><div class="f"><span>'+t.asof+' '+esc(D.asof)+' · GOV RADAR · '+esc(t.note)+'</span><a class="go" href="'+B+t.url+'?utm_source='+S+'&utm_medium=card" target="_blank" rel="noopener">'+esc(t.all)+' →</a></div></section>';
 var r=el.attachShadow?el.attachShadow({mode:"open"}):el;r.innerHTML=h}
function run(){if(!document.getElementById("gv-cyber-ff")){var st=document.createElement("style");st.id="gv-cyber-ff";st.textContent=FF;document.head.appendChild(st)}var a=document.querySelectorAll("[data-gv-cyber]");for(var i=0;i<a.length;i++)render(a[i])}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",run);else run()})();
"""
open(os.path.join(CY, "card.js"), "w", encoding="utf-8").write(JS.replace("__DATA__", json.dumps(D, ensure_ascii=False, separators=(",", ":"))))
os.makedirs(os.path.join(CY, "card"), exist_ok=True)
open(os.path.join(CY, "card", "index.html"), "w", encoding="utf-8").write("""<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>사이버 공격 카드 미리보기 · GOV RADAR</title>
<style>@font-face{font-family:"WMM Nexon";src:local("NEXON Lv1 Gothic OTF"),url(/assets/fonts/NEXONLv1GothicOTF.woff) format("woff")}body{margin:0;background:#f4f6f9;font-family:"WMM Nexon",sans-serif;color:#0d1b2e}main{max-width:1180px;margin:0 auto;padding:32px 16px}h1{font-size:22px}pre{background:#fff;padding:14px;overflow:auto;font-size:13px}section{margin:0 0 40px}</style></head><body><main>
<h1>다른 사이트에 넣는 사이버 공격 카드 — 미리보기</h1><p>아래 두 줄을 붙이면 같은 카드가 나옵니다. 사건과 판정은 GOV RADAR 사이버 공격 페이지에 게시된 것만 씁니다.</p>
<pre>&lt;div data-gv-cyber data-site="wmm" data-lang="ko" data-n="4"&gt;&lt;/div&gt;
&lt;script src="https://radar.wmm-hoa.com/cyber/card.js" defer&gt;&lt;/script&gt;</pre>
<section><h2>WMM용 (한국어)</h2><div data-gv-cyber data-site="wmm" data-lang="ko" data-n="4"></div></section>
<section><h2>GCSME용 (한국어)</h2><div data-gv-cyber data-site="gcsme" data-theme="light" data-lang="ko" data-n="4"></div></section>
<section><h2>English</h2><div data-gv-cyber data-site="gcsme" data-lang="en" data-n="4"></div></section>
</main><script src="/cyber/card.js" defer></script></body></html>""")
print(len(ko), len(en), asof, [x["v"] for x in ko[:6]])
